<script>
(function(){
  "use strict";

  /* ---------- Nav scroll state ---------- */
  var nav = document.getElementById('nav');
  function onScroll(){ nav.classList.toggle('scrolled', window.scrollY > 24); }
  window.addEventListener('scroll', onScroll, {passive:true});
  onScroll();

  /* ---------- Mobile menu ---------- */
  var toggle = document.getElementById('navToggle');
  var links = document.getElementById('navLinks');
  toggle.addEventListener('click', function(){
    var open = links.classList.toggle('mobile-open');
    toggle.classList.toggle('open', open);
    toggle.setAttribute('aria-expanded', String(open));
  });
  links.addEventListener('click', function(e){
    if(e.target.tagName === 'A'){
      links.classList.remove('mobile-open');
      toggle.classList.remove('open');
      toggle.setAttribute('aria-expanded','false');
    }
  });

  /* ---------- Stars ---------- */
  var starLayer = document.getElementById('stars');
  if(starLayer){
    for(var i=0;i<72;i++){
      var s = document.createElement('span');
      s.className = 'star';
      var size = Math.random() < 0.82 ? 2 : 3;
      s.style.width = s.style.height = size + 'px';
      s.style.left = (Math.random()*100) + '%';
      s.style.top = (Math.random()*100) + '%';
      s.style.animationDelay = (Math.random()*6).toFixed(2) + 's';
      s.style.animationDuration = (3.5 + Math.random()*5).toFixed(2) + 's';
      starLayer.appendChild(s);
    }
  }

  /* ---------- Next departure countdown ---------- */
  var schedule = ['21:40','23:15','01:05','03:30'];
  var next = function(now){
    for(var i=0;i<schedule.length;i++){
      var parts = schedule[i].split(':');
      var d = new Date(now);
      d.setHours(+parts[0], +parts[1], 0, 0);
      if(d.getTime() > now.getTime()) return {t: schedule[i], at: d};
    }
    var p = schedule[0].split(':');
    var tomorrow = new Date(now);
    tomorrow.setDate(tomorrow.getDate() + 1);
    tomorrow.setHours(+p[0], +p[1], 0, 0);
    return {t: schedule[0], at: tomorrow};
  };
  var pad = function(n){ return String(n).padStart(2,'0'); };
  var pill = document.getElementById('countdownText');
  var note = document.getElementById('countdownNote');
  function tick(){
    var now = new Date();
    var nd = next(now);
    var diff = Math.max(0, nd.at.getTime() - now.getTime());
    var h = Math.floor(diff/3600000);
    var m = Math.floor((diff%3600000)/60000);
    var s = Math.floor((diff%60000)/1000);
    var str = 'in ' + pad(h) + ':' + pad(m) + ':' + pad(s);
    if(pill) pill.textContent = 'Next departure ' + nd.t + ' · ' + str;
    if(note) note.textContent = 'Next departure ' + nd.t + ' — ' + str;
  }
  tick();
  setInterval(tick, 1000);

  /* ---------- Scroll reveal ---------- */
  var revealEls = document.querySelectorAll('.reveal');
  if('IntersectionObserver' in window){
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(en){
        if(en.isIntersecting){
          en.target.classList.add('in');
          io.unobserve(en.target);
        }
      });
    }, {threshold:0.12, rootMargin:'0px 0px -40px 0px'});
    revealEls.forEach(function(el){ io.observe(el); });
  } else {
    revealEls.forEach(function(el){ el.classList.add('in'); });
  }

  /* ---------- Footer year ---------- */
  document.getElementById('year').textContent = new Date().getFullYear();
})();
</script>
